    const uint8_t* scales = block + 4;                  // 12 bytes
    const uint8_t* q = block + 16;                      // 128 bytes
    float* y = out;
    int is = 0;
    for (int j = 0; j < 256; j += 64) {
        uint8_t sc, m;
        get_scale_min_k4(is + 0, scales, sc, m);
        const float d1 = d * (float)sc, m1 = mn * (float)m;
        get_scale_min_k4(is + 1, scales, sc, m);
